"""

# ---------------------------------------------------------------------
# The parser
# ---------------------------------------------------------------------

type
  VectorRecord = Table[string, string]

  VectorSetup = object
    section: string
    fields: VectorRecord
    encryptions: seq[VectorRecord]
    exports: seq[VectorRecord]

  ParsedAppendix = object
    setups: seq[VectorSetup]
    unparsedLines: int
      ## Lines the parser did not place. Asserted to be zero: a parser
      ## that silently drops what it does not recognise is how a fixture
      ## set shrinks without anyone noticing.

proc splitField(line: string): tuple[ok: bool, key, value: string] =
  ## `   name: value` — the RFC's field shape. Anything else (a wrapped
  ## hex continuation, in practice) is not a field.
  if not line.startsWith("   "): return (false, "", "")
  let body = line[3 .. ^1]
  let colon = body.find(':')
  if colon <= 0: return (false, "", "")
  let key = body[0 ..< colon]
  for c in key:
    if c notin {'A' .. 'Z', 'a' .. 'z', '0' .. '9', '_', ' '}:
      return (false, "", "")
  var value = body[colon + 1 .. ^1]
  if value.len > 0 and value[0] == ' ': value = value[1 .. ^1]
  (true, key, value)

proc parseAppendix(text: string): ParsedAppendix =
  ## Walks the RFC text. A heading ending in "Setup Information" opens a
  ## setup; "Encryptions" and "Exported Values" open sub-records of the
  ## setup above them, one per `sequence number` / `exporter_context`
  ## key. Continuation lines append to the field they follow.
  var mode = "none"
  var lastKey = ""
  for rawLine in text.splitLines():
    if rawLine.strip().len == 0: continue
    if not rawLine.startsWith("   "):
      let heading = rawLine.strip()
      if heading.endsWith("Setup Information"):
        result.setups.add VectorSetup(section: heading)
        mode = "setup"
      elif heading.endsWith("Encryptions"):
        mode = "encryptions"
      elif heading.endsWith("Exported Values"):
        mode = "exports"
      else:
        mode = "none"
      lastKey = ""
      continue
    let (ok, key, value) = splitField(rawLine)
    if ok:
      if result.setups.len == 0:
        result.unparsedLines.inc
        continue
      lastKey = key
      case mode
      of "setup":
        result.setups[^1].fields[key] = value
      of "encryptions":
        if key == "sequence number":
          result.setups[^1].encryptions.add initTable[string, string]()
        if result.setups[^1].encryptions.len == 0:
          result.unparsedLines.inc
        else:
          result.setups[^1].encryptions[^1][key] = value
      of "exports":
        if key == "exporter_context":
          result.setups[^1].exports.add initTable[string, string]()
        if result.setups[^1].exports.len == 0:
          result.unparsedLines.inc
        else:
          result.setups[^1].exports[^1][key] = value
      else:
        result.unparsedLines.inc
      continue
    # A continuation of the field above it, which the RFC wraps at 64
    # hex characters.
    let cont = rawLine.strip()
    var placed = false
    if lastKey.len > 0 and result.setups.len > 0:
      case mode
      of "setup":
        result.setups[^1].fields[lastKey] =
          result.setups[^1].fields[lastKey] & cont
        placed = true
      of "encryptions":
        if result.setups[^1].encryptions.len > 0:
          result.setups[^1].encryptions[^1][lastKey] =
            result.setups[^1].encryptions[^1][lastKey] & cont
          placed = true
      of "exports":
        if result.setups[^1].exports.len > 0:
          result.setups[^1].exports[^1][lastKey] =
            result.setups[^1].exports[^1][lastKey] & cont
          placed = true
      else: discard
    if not placed: result.unparsedLines.inc

let Appendix = parseAppendix(RfcAppendixA)

proc hx(where, s: string): string = hexToBytes(where, s)

proc aeadForId(id: int): HpkeAead =
  case id
  of 0x0001: haAes128Gcm
  of 0x0003: haChaCha20Poly1305
  else:
    raise newException(ValueError,
      "this build implements no aead_id " & $id & "; the vector corpus " &
      "must not contain one it cannot name")

