suite "hpke primitives pinned against their own rfcs":

  test "t_hkdf_sha256_matches_rfc5869":
    for v in Rfc5869:
      let ikm = hx("ikm", v[0])
      let salt = hx("salt", v[1])
      let info = hx("info", v[2])
      let prk = hkdfExtract(salt, ikm)
      check bytesToHex(prk) == v[4]
      let okm = hkdfExpand(prk, info, parseInt(v[3]))
      check bytesToHex(okm) == v[5]
      check okm.len == parseInt(v[3])

  test "t_x25519_matches_rfc7748":
    # §5.2 — the two scalar-multiplication vectors. These are what say
    # which end of the scalar BearSSL wants.
    for v in Rfc7748Scalarmult:
      check bytesToHex(dh(hx("scalar", v[0]), hx("u", v[1]))) == v[2]
    # §6.1 — the Diffie-Hellman vector, including each public key from
    # the base point, which exercises `publicKey`'s separate path.
    let a = hx("a", Rfc7748AlicePriv)
    let b = hx("b", Rfc7748BobPriv)
    check bytesToHex(publicKey(a)) == Rfc7748AlicePub
    check bytesToHex(publicKey(b)) == Rfc7748BobPub
    check bytesToHex(dh(a, hx("pkB", Rfc7748BobPub))) == Rfc7748Shared
    check bytesToHex(dh(b, hx("pkA", Rfc7748AlicePub))) == Rfc7748Shared

# ---------------------------------------------------------------------
# The framing the composition rests on
# ---------------------------------------------------------------------

suite "hpke labeled-kdf framing":

  test "t_hpke_labels_are_unambiguous_per_function":
    # The property the module header's framing argument rests on,
    # computed from the arrays the module actually uses.
    check labelsAreUnambiguous(ExtractLabels)
    check labelsAreUnambiguous(ExpandLabels)
    check LabelsAreUnambiguous ==
      "no label is a prefix of another label used by the same function"
    # And the reason the two sets are SEPARATE rather than one: merged,
    # the property is false, because "sec" is a prefix of "secret". A
    # later tidy-up that concatenates them would be caught here.
    var merged: seq[string] = @[]
    for l in ExtractLabels: merged.add l
    for l in ExpandLabels: merged.add l
    check not labelsAreUnambiguous(merged)
    check "secret" in ExtractLabels
    check "sec" in ExpandLabels

  test "t_hpke_key_schedule_context_is_framed_by_fixed_widths":
    # `key_schedule_context` joins two caller-supplied values. If they
    # were joined raw, moving one byte from `psk_id` to `info` would
    # leave the joined bytes unchanged — the exact ambiguity the sibling
    # binding construction had to be repaired for. They are hashed to a
    # fixed width first, so the boundary cannot move.
    let ss = hx("ss", "00" .repeat(32))
    let psk = hx("psk", "aa".repeat(32))
    let a = keySchedule(haAes128Gcm, hmPsk, ss, "C", psk, "AB")
    let b = keySchedule(haAes128Gcm, hmPsk, ss, "BC", psk, "A")
    check "AB" & "C" == "A" & "BC"
    check a.keyScheduleContext != b.keyScheduleContext
    check a.key != b.key
    # …and the width itself, across every psk_id and info length in play.
    for ctx in [a, b]:
      check ctx.keyScheduleContext.len == 1 + 2 * Nh
      check ctx.keyScheduleContext[0] == char(ord(hmPsk))

  test "t_hpke_labeled_kdf_preimages_are_the_rfc_strings":
    # `labeledExtractPreimage` and `labeledExpandInfo` are exported so the
    # framing can be pinned as BYTES rather than only through a digest
    # that happens to agree — and until this case existed nothing used
    # them, which made that sentence a claim with no case behind it.
    #
    # RFC 9180 §4:
    #   LabeledExtract(salt, label, ikm):
    #     labeled_ikm  = "HPKE-v1" ‖ suite_id ‖ label ‖ ikm
    #   LabeledExpand(prk, label, info, L):
    #     labeled_info = I2OSP(L, 2) ‖ "HPKE-v1" ‖ suite_id ‖ label ‖ info
    #
    # The expected bytes below are assembled from that definition and from
    # the suite ids the case above pins, not from this module's output.
    let info = hx("info", "4f6465206f6e2061204772656369616e2055726e")
    check bytesToHex(labeledExtractPreimage(
      suiteIdFor(haAes128Gcm), "info_hash", info)) ==
      "48504b452d7631" & "48504b45002000010001" & "696e666f5f68617368" &
      "4f6465206f6e2061204772656369616e2055726e"
    let ikmE = hx("ikmE",
      "7268600d403fce431561aef583ee1613527cff655c1343f29812e66706df3234")
    check bytesToHex(labeledExtractPreimage(
      kemSuiteId(KemIdX25519HkdfSha256), "dkp_prk", ikmE)) ==
      "48504b452d7631" & "4b454d0020" & "646b705f70726b" &
      "7268600d403fce431561aef583ee1613527cff655c1343f29812e66706df3234"
    check bytesToHex(labeledExpandInfo(
      kemSuiteId(KemIdX25519HkdfSha256), "sk", "", Nsk)) ==
      "0020" & "48504b452d7631" & "4b454d0020" & "736b"
    # The only variable-length part is last, which is what makes the
    # string unambiguous — demonstrated rather than asserted: moving a
    # byte from the label into the ikm cannot reproduce the same preimage
    # unless the labels are not prefix-free, which the case above checks.
    check labeledExtractPreimage(suiteIdFor(haAes128Gcm), "info_hash",
                                 info).len ==
      HpkeVersionLabel.len + 10 + "info_hash".len + info.len
    check labeledExpandInfo(kemSuiteId(KemIdX25519HkdfSha256), "sk", "",
                            Nsk).len == 2 + HpkeVersionLabel.len + 5 + 2

  test "t_hpke_suite_ids_are_fixed_width":
    # RFC 9180 §5.1: "KEM" ‖ I2OSP(kem_id, 2) and
    # "HPKE" ‖ I2OSP(kem_id, 2) ‖ I2OSP(kdf_id, 2) ‖ I2OSP(aead_id, 2).
    check bytesToHex(kemSuiteId(KemIdX25519HkdfSha256)) == "4b454d0020"
    check kemSuiteId(KemIdX25519HkdfSha256).len == 5
    check bytesToHex(suiteIdFor(haAes128Gcm)) == "48504b4500200001" & "0001"
    check bytesToHex(suiteIdFor(haChaCha20Poly1305)) ==
      "48504b4500200001" & "0003"
    check suiteIdFor(haAes128Gcm).len == 10
    check suiteIdFor(haChaCha20Poly1305).len == 10
    check HpkeVersionLabel == "HPKE-v1"

# ---------------------------------------------------------------------
# RFC 9180 Appendix A.1 and A.2
# ---------------------------------------------------------------------

suite "hpke rfc 9180 appendix a vectors":

  test "t_hpke_vector_corpus_is_intact":
    # The corpus has to be constrained by its own gate, or it can shrink
    # to nothing and every case below passes vacuously.
    check Appendix.unparsedLines == 0
    check Appendix.setups.len == 8
    var encryptions = 0
    var exports = 0
    for s in Appendix.setups:
      check s.encryptions.len == 6
      check s.exports.len == 3
      encryptions += s.encryptions.len
      exports += s.exports.len
      for required in ["mode", "kem_id", "kdf_id", "aead_id", "info",
                       "ikmE", "pkEm", "skEm", "ikmR", "pkRm", "skRm",
                       "enc", "shared_secret", "key_schedule_context",
                       "secret", "key", "base_nonce", "exporter_secret"]:
        check required in s.fields
        check s.fields[required].len > 0 or required == "info"
      for e in s.encryptions:
        for required in ["sequence number", "pt", "aad", "nonce", "ct"]:
          check required in e
      for x in s.exports:
        for required in ["exporter_context", "L", "exported_value"]:
          check required in x
    check encryptions == 48
    check exports == 24
    # Both suites, all four modes, once each.
    var seen: seq[string] = @[]
    for s in Appendix.setups:
      seen.add s.fields["aead_id"] & "/" & s.fields["mode"]
    check seen == @["1/0", "1/1", "1/2", "1/3",
                    "3/0", "3/1", "3/2", "3/3"]

  test "t_hpke_rfc9180_vectors":
    var compared = 0
    # `got` is bound to a `let` before it is compared. `unittest.check`
    # re-expands its operands to print them, and `seal` advances a
    # sequence number — an operand with a side effect would be run twice
    # and the second run would report a different, correct-looking
    # answer. That is not a hypothetical: it happened here first.
    template pin(what: string; got, want: string) =
      block:
        let g = got
        let w = want
        if g != w:
          checkpoint("vector " & what & " in " & s.section)
        check g == w
        compared.inc

    for s in Appendix.setups:
      let f = s.fields
      let mode = HpkeMode(parseInt(f["mode"]))
      check parseInt(f["kem_id"]) == int(KemIdX25519HkdfSha256)
      check parseInt(f["kdf_id"]) == int(KdfIdHkdfSha256)
      let aead = aeadForId(parseInt(f["aead_id"]))
      let info = hx("info", f["info"])
      let psk =
        if mode in {hmPsk, hmAuthPsk}: hx("psk", f["psk"]) else: DefaultPsk
      let pskId =
        if mode in {hmPsk, hmAuthPsk}: hx("psk_id", f["psk_id"])
        else: DefaultPskId

      # Key derivation, both parties, from the RFC's ikm.
      let kpE = deriveKeyPair(hx("ikmE", f["ikmE"]))
      pin "skEm", bytesToHex(kpE.sk), f["skEm"]
      pin "pkEm", bytesToHex(kpE.pk), f["pkEm"]
      let kpR = deriveKeyPair(hx("ikmR", f["ikmR"]))
      pin "skRm", bytesToHex(kpR.sk), f["skRm"]
      pin "pkRm", bytesToHex(kpR.pk), f["pkRm"]
      # …and the public half again, off the private key rather than the
      # seed, so a broken derivation and a broken base-point
      # multiplication cannot cancel each other out.
      pin "pkEm from skEm", bytesToHex(publicKey(hx("skEm", f["skEm"]))),
          f["pkEm"]

      var enc, sharedSecret: string
      var recipient: HpkeContext
      var sender: HpkeContext
      if mode in {hmAuth, hmAuthPsk}:
        let kpS = deriveKeyPair(hx("ikmS", f["ikmS"]))
        pin "skSm", bytesToHex(kpS.sk), f["skSm"]
        pin "pkSm", bytesToHex(kpS.pk), f["pkSm"]
        let got = authEncapWithEphemeral(kpR.pk, kpE, kpS.sk)
        enc = got.enc
        sharedSecret = got.sharedSecret
        # The receiver's half, which is a different computation.
        pin "shared_secret from authDecap",
            bytesToHex(authDecap(enc, kpR.sk, kpS.pk)), f["shared_secret"]
        if mode == hmAuth:
          sender = setupAuthS(aead, kpR.pk, kpE, info, kpS.sk).ctx
          recipient = setupAuthR(aead, enc, kpR.sk, info, kpS.pk)
        else:
          sender = setupAuthPskS(
            aead, kpR.pk, kpE, info, psk, pskId, kpS.sk).ctx
          recipient = setupAuthPskR(
            aead, enc, kpR.sk, info, psk, pskId, kpS.pk)
      else:
        let got = encapWithEphemeral(kpR.pk, kpE)
        enc = got.enc
        sharedSecret = got.sharedSecret
        pin "shared_secret from decap", bytesToHex(decap(enc, kpR.sk)),
            f["shared_secret"]
        if mode == hmBase:
          sender = setupBaseS(aead, kpR.pk, kpE, info).ctx
          recipient = setupBaseR(aead, enc, kpR.sk, info)
        else:
          sender = setupPskS(aead, kpR.pk, kpE, info, psk, pskId).ctx
          recipient = setupPskR(aead, enc, kpR.sk, info, psk, pskId)

      pin "enc", bytesToHex(enc), f["enc"]
      pin "shared_secret", bytesToHex(sharedSecret), f["shared_secret"]

      let ctx = keySchedule(aead, mode, sharedSecret, info, psk, pskId)
      pin "key_schedule_context", bytesToHex(ctx.keyScheduleContext),
          f["key_schedule_context"]
      pin "secret", bytesToHex(ctx.secret), f["secret"]
      pin "key", bytesToHex(ctx.key), f["key"]
      pin "base_nonce", bytesToHex(ctx.baseNonce), f["base_nonce"]
      pin "exporter_secret", bytesToHex(ctx.exporterSecret),
          f["exporter_secret"]

      # The four setup entry points must agree with the key schedule they
      # are supposed to be calling; otherwise the vectors above would pin
      # a function nothing in production reaches.
      check sender.key == ctx.key
      check sender.baseNonce == ctx.baseNonce
      check sender.exporterSecret == ctx.exporterSecret
      check recipient.key == ctx.key
      check recipient.baseNonce == ctx.baseNonce
      check recipient.exporterSecret == ctx.exporterSecret
      check recipient.mode == mode

      for e in s.encryptions:
        let n = parseBiggestUInt(e["sequence number"])
        sender.setSequenceNumber(n)
        pin "nonce", bytesToHex(sender.computeNonce()), e["nonce"]
        pin "ct", bytesToHex(
              sender.seal(hx("aad", e["aad"]), hx("pt", e["pt"]))), e["ct"]
        # The receiver half, driven off the RFC's ciphertext rather than
        # the one just produced.
        recipient.setSequenceNumber(n)
        pin "pt", bytesToHex(
              recipient.open(hx("aad", e["aad"]), hx("ct", e["ct"]))), e["pt"]
        check sender.seq == n + 1
        check recipient.seq == n + 1

      for x in s.exports:
        let want = x["exported_value"]
        pin "exported_value", bytesToHex(ctx.exportSecret(
              hx("exporter_context", x["exporter_context"]),
              parseInt(x["L"]))), want

    # 8 setups x 13 pinned values, plus 2 more on each of the 4
    # authenticated setups, plus 3 per encryption over 48 encryptions,
    # plus one per exported value over 24.
    check compared == 8 * 13 + 4 * 2 + 48 * 3 + 24
    check compared == 280
